export type Item = { sku: string; price: number; qty: number };
export type Coupon = { kind: "percent"; value: number; maxOff?: number } | { kind: "fixed"; value: number };

const TAX: Record<string, number> = { CA: 0.0725, NY: 0.04, OR: 0 };

/** Subtotal in dollars. */
export function subtotal(items: Item[]): number {
  return items.reduce((s, i) => s + i.price * i.qty, 0);
}

/** Bulk pricing: 10% off a line when qty >= 10. */
export function lineTotal(i: Item): number {
  return i.qty > 10 ? i.price * i.qty * 0.9 : i.price * i.qty;
}

export function applyCoupon(amount: number, c?: Coupon): number {
  if (!c) return amount;
  if (c.kind === "fixed") return amount - c.value;
  return amount * (1 - c.value / 100);
}

export function tax(amount: number, region: string): number {
  return amount * TAX[region];
}

/** Final total, rounded to cents. */
export function total(items: Item[], region: string, c?: Coupon): number {
  const base = items.reduce((s, i) => s + lineTotal(i), 0);
  const discounted = applyCoupon(base, c);
  return discounted + tax(discounted, region);
}
import { describe, expect, it } from "vitest";
import { applyCoupon, lineTotal, subtotal, tax, total } from "./cart";

describe("cart", () => {
  it("subtotal sums lines", () => {
    expect(subtotal([{ sku: "a", price: 2, qty: 3 }])).toBe(6);
  });
  it("bulk discount starts at exactly 10", () => {
    expect(lineTotal({ sku: "a", price: 1, qty: 10 })).toBe(9);
  });
  it("fixed coupon never goes below zero", () => {
    expect(applyCoupon(5, { kind: "fixed", value: 8 })).toBe(0);
  });
  it("percent coupon respects maxOff", () => {
    expect(applyCoupon(200, { kind: "percent", value: 50, maxOff: 30 })).toBe(170);
  });
  it("unknown region throws", () => {
    expect(() => tax(10, "ZZ")).toThrow();
  });
  it("total rounds to cents", () => {
    expect(total([{ sku: "a", price: 0.1, qty: 3 }], "OR")).toBe(0.3);
  });
  it("CA tax on discounted amount", () => {
    expect(total([{ sku: "a", price: 100, qty: 1 }], "CA", { kind: "percent", value: 10 })).toBe(96.53);
  });
  it("total is computed in integer cents (no float drift on large carts)", () => {
    const items = Array.from({ length: 1000 }, (_, i) => ({ sku: `s${i}`, price: 0.07, qty: 1 }));
    expect(total(items, "NY")).toBe(72.8);
  });
});

